package com.github.rcubedev.utils.event.generated;

import com.github.rcubedev.utils.event.api.Event;
import com.github.rcubedev.utils.event.api.Priority;
import org.jetbrains.annotations.ApiStatus;

/**
 * An invoker bound to its target event type, execution priority and
 * cancellation handling behaviour.
 *
 * @apiNote This interface is implemented solely by classes generated by the
 *          annotation processor and should not be implemented directly
 * @param <T> the listener type
 * @param <E> the specific event type handled
 */
@ApiStatus.Internal
public interface EventSubscriberInvoker<T, E extends Event> {

    /**
     * Returns the target event type this invoker listens for.
     *
     * @return the event class
     * @implSpec Implementations must be side-effect-free. Successive calls must return
     *           the exact same {@link Class} instance.
     */
    Class<E> eventType();

    /**
     * Returns the execution priority of this handler method.
     *
     * @return the handler priority
     * @implSpec Implementations must be side-effect-free. Successive calls must return
     *           the exact same {@link Priority} instance.
     */
    Priority priority();

    /**
     * Indicates whether cancelled events should be ignored by this handler.
     *
     * @return {@code true} if cancelled events should be ignored
     * @implSpec Implementations must be side-effect-free. Successive calls must return
     *           the exact same result.
     */
    boolean ignoreCancelled();

    /**
     * Invokes the target handler method on the specified listener instance.
     *
     * @param listener the target listener instance
     * @param event the event to dispatch
     */
    // possibly make this default & delegate to a binding factory provider method here & make a way to cv this to HandlerFactory
    void invoke(T listener, E event);
}
